import { getApiKey } from '../openai.js';

const OPENAI_BASE = 'https://api.openai.com/v1';

/**
 * The actual Instagram/Facebook post-caption field (up to 2,200 chars,
 * hashtags inline) — spec §9: "generated by the same copy pipeline,
 * editable in the drill-in. This is the caption *field*, separate from
 * the on-image text." A different job from generate-captions.js (which
 * writes the punchy ON-IMAGE overlay text): this expands on the topic in
 * paragraph form for the IG/FB caption box itself, with a real CTA and
 * hashtags — nobody reads this off the image, so it can actually explain
 * itself.
 * @param {{ audience: 'consumer'|'contractor', topic: { title: string, hook: string, points: string[], closer: string } }} opts
 * @returns {Promise<string>}
 */
export async function generatePostCaption({ audience, topic }) {
  const key = getApiKey();
  if (!key) throw new Error('OPENAI_API_KEY is not configured.');

  const audienceNote = audience === 'consumer'
    ? 'Audience: homeowners considering a DIY epoxy floor. End with a soft nudge to get a free quote from a real pro at epoxygrind.com.'
    : 'Audience: epoxy/concrete-coating contractors. End with a soft nudge to run their site through the free audit at epoxygrind.com.';

  const res = await fetch(`${OPENAI_BASE}/chat/completions`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'gpt-4o',
      response_format: { type: 'json_object' },
      messages: [
        {
          role: 'system',
          content: `You write the Instagram/Facebook POST CAPTION (the text field below a carousel post, not text on the images themselves) for EpoxyGrind's daily carousel. Confident, a little mean, never corporate — same snarky voice as the rest of this account.

${audienceNote}

Structure:
- First line is a strong hook (shows before "more" gets cut off on IG — keep it under ~100 characters and make it stand alone).
- 2-4 short paragraphs/lines expanding on the topic's points in plain language (not just repeating the image captions verbatim).
- A clear call to action mentioning epoxygrind.com.
- End with 5-8 relevant hashtags on their own line (mix of broad: #epoxyflooring #garageflooring, and specific to the topic).
- Plain text only — no markdown, no emoji spam (0-2 emoji max, only if they earn their place).
- Under 2200 characters total.

Return JSON only: {"caption": string}`,
        },
        {
          role: 'user',
          content: `Topic: "${topic.title}"
Hook: ${topic.hook}
Points:
1. ${topic.points[0]}
2. ${topic.points[1]}
3. ${topic.points[2]}
4. ${topic.points[3]}
Closer: ${topic.closer}`,
        },
      ],
      max_tokens: 700,
    }),
  });

  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Post caption generation failed: ${res.status} ${err}`);
  }

  const data = await res.json();
  const raw = data.choices?.[0]?.message?.content;
  if (!raw) throw new Error('No post caption content returned.');

  const parsed = JSON.parse(raw);
  if (typeof parsed.caption !== 'string' || !parsed.caption.trim()) {
    throw new Error(`Expected a non-empty caption string, got ${JSON.stringify(parsed.caption)}`);
  }
  return parsed.caption.trim();
}
